/**
 * 每个预设图标各自的 viewBox。
 *
 * ★ 为什么不能统一写死 0 0 1024 1024 ★
 *   原画布都是 1024，但图形本身在画布里的占位差很多：
 *     通讯 / 财富的圆  ≈ 1023（几乎顶满画布）
 *     快捷支付         ≈ 796
 *     投资             ≈ 894
 *   统一用原画布，就会出现「有的图标顶到格子边、有的缩在中间」，
 *   一排看过去大小不一（用户直接指出「倒数第二个感觉比其他小」）。
 *   所以这里按每个图标的**真实包围盒**取一个正方形视口，让它们占满同样的视觉尺寸。
 *
 * ★ 为什么是正方形、且不变形 ★
 *   取长边作为边长并居中，宽高比原样保留 —— 只是裁掉四周多余的留白，
 *   几何形状一点没动。图标格子本身是正方形（78rpx），这样上下左右刚好对齐。
 */
const PRESET_VIEW_BOXES = (() => {
  const map = {}
  for (const key of Object.keys(PRESET_PATHS)) {
    let b = null
    for (const d of PRESET_PATHS[key]) {
      const bb = parsePathBounds(d)
      if (!bb) continue
      if (!b) b = { ...bb }
      else {
        b.minX = Math.min(b.minX, bb.minX); b.maxX = Math.max(b.maxX, bb.maxX)
        b.minY = Math.min(b.minY, bb.minY); b.maxY = Math.max(b.maxY, bb.maxY)
      }
    }
    if (!b) { map[key] = '0 0 1024 1024'; continue }
    // 个别路径的手柄点略微超出画布（原图就是被裁掉的），先夹回 1024 画布再算，
    // 否则视口会比原图多露出一圈原本看不见的线。
    b.minX = Math.max(0, b.minX); b.minY = Math.max(0, b.minY)
    b.maxX = Math.min(1024, b.maxX); b.maxY = Math.min(1024, b.maxY)
    const w = b.maxX - b.minX
    const h = b.maxY - b.minY
    // 留 2% 边距，和品牌图标 estimateViewBox 的取法保持一致
    const side = Math.max(w, h) * 1.04
    const cx = (b.minX + b.maxX) / 2
    const cy = (b.minY + b.maxY) / 2
    map[key] = `${(cx - side / 2).toFixed(2)} ${(cy - side / 2).toFixed(2)} ${side.toFixed(2)} ${side.toFixed(2)}`
  }
  return map
})()

