/* -------------------------------------------------- viewBox 估算（品牌用） */

/**
 * 从 path 的 d 属性解析出真实包围盒（含所有控制点，保证不裁剪）。
 *
 * ★ 为什么手写解析器而不是用库 ★
 *   图标 path 来自 simple-icons / 各家银行标志，语法是标准 SVG path。
 *   项目没有引入 SVG 解析依赖，这里用一个轻量解析器处理常见的
 *   命令：M L H V C S Q T A Z（含相对/绝对）。控制点也计入包围盒，
 *   因为贝塞尔曲线不会越过控制点凸包，这样一定不会裁到曲线。
 *
 * ★ 品牌和预设都要走这里 ★
 *   品牌路径的坐标系各不相同（simple-icons 是 24x24，各家银行是 1024x1024），
 *   必须按真实包围盒裁掉留白，24px 下才够大。
 *   用户指定的那 6 个虽然都是 1024 画布，但图形占位差得多
 *   （通讯/财富几乎顶满、快捷支付只占 796），统一用原画布会一大一小，
 *   所以也按包围盒取正方形视口（见 PRESET_VIEW_BOXES）。
 *
 * @param {string} d path 的 d 属性
 * @returns {{minX:number,minY:number,maxX:number,maxY:number}|null}
 */
function parsePathBounds(d) {
  const tokens = d.match(/[a-zA-Z]|-?\d*\.?\d+/g) || []
  let i = 0
  let x = 0, y = 0, sx = 0, sy = 0
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity
  let cmd = ''
  const num = () => Number(tokens[i++])
  const upd = (px, py) => {
    if (px < minX) minX = px
    if (px > maxX) maxX = px
    if (py < minY) minY = py
    if (py > maxY) maxY = py
  }
  while (i < tokens.length) {
    const t = tokens[i]
    if (/[a-zA-Z]/.test(t)) { cmd = t; i++ } else if (!cmd) { i++; continue }
    const rel = cmd >= 'a' && cmd <= 'z'
    const c = cmd.toUpperCase()
    if (c === 'M' || c === 'L') {
      const nx = rel ? x + num() : num()
      const ny = rel ? y + num() : num()
      upd(nx, ny); x = nx; y = ny
      if (c === 'M') { sx = nx; sy = ny }
      // M 后面若还有坐标（隐式多段线），按 L 处理
      if (c === 'M' && i < tokens.length && !/[a-zA-Z]/.test(tokens[i])) cmd = rel ? 'l' : 'L'
    } else if (c === 'H') {
      const nx = rel ? x + num() : num()
      upd(nx, y); x = nx
    } else if (c === 'V') {
      const ny = rel ? y + num() : num()
      upd(x, ny); y = ny
    } else if (c === 'C') {
      const x1 = rel ? x + num() : num(), y1 = rel ? y + num() : num()
      const x2 = rel ? x + num() : num(), y2 = rel ? y + num() : num()
      const nx = rel ? x + num() : num(), ny = rel ? y + num() : num()
      upd(x1, y1); upd(x2, y2); upd(nx, ny); x = nx; y = ny
    } else if (c === 'S' || c === 'Q') {
      const x1 = rel ? x + num() : num(), y1 = rel ? y + num() : num()
      const nx = rel ? x + num() : num(), ny = rel ? y + num() : num()
      upd(x1, y1); upd(nx, ny); x = nx; y = ny
    } else if (c === 'T') {
      const nx = rel ? x + num() : num(), ny = rel ? y + num() : num()
      upd(nx, ny); x = nx; y = ny
    } else if (c === 'A') {
      // 圆弧：7 个参数 rx ry rot laf sf x y，端点才是 x,y（前 5 个跳过）
      num(); num(); num(); num(); num()
      const nx = rel ? x + num() : num(), ny = rel ? y + num() : num()
      upd(nx, ny); x = nx; y = ny
    } else if (c === 'Z') {
      upd(sx, sy); x = sx; y = sy
    }
  }
  if (minX === Infinity) return null
  return { minX, minY, maxX, maxY }
}

/**
 * 从一组 path 估算 viewBox（真实包围盒，保留原始宽高比）。
 *
 * ★ 为什么要真实包围盒而不是正方形 ★
 *   很多品牌图标本来就是非 1:1（wechat 约 1.22、visa 约 1.79），
 *   用正方形 viewBox 会把它们压扁或上下留白。
 *   这里返回 `minX minY width height`，让 <image mode="aspectFit">
 *   按真实比例显示。
 *
 * ★ 加一点 padding ★
 *   包围盒是控制点凸包，曲线可能略微超出；加 2% 内边距避免裁到边。
 *
 * ★ 只有品牌图标用这个 ★
 *   用户指定的 6 个预设图标固定用 PRESET_VIEW_BOX（原始 1024 画布），
 *   它们本来就是按同一块画布设计的，各自裁包围盒反而会让 6 个大小不齐。
 *
 * @param {string[]} paths path 的 d 属性数组
 * @returns {string} viewBox 字符串；解析失败回退 24x24
 */
function estimateViewBox(paths) {
  let b = null
  for (const d of paths) {
    const bb = parsePathBounds(d)
    if (!bb) continue
    if (!b) b = { ...bb }
    else {
      b.minX = Math.min(b.minX, bb.minX); b.maxX = Math.max(b.maxX, bb.maxX)
      b.minY = Math.min(b.minY, bb.minY); b.maxY = Math.max(b.maxY, bb.maxY)
    }
  }
  if (!b) return '0 0 24 24'
  const w = b.maxX - b.minX
  const h = b.maxY - b.minY
  if (w <= 0 || h <= 0) return '0 0 24 24'
  const pad = Math.max(w, h) * 0.02
  const minX = b.minX - pad
  const minY = b.minY - pad
  const vw = w + pad * 2
  const vh = h + pad * 2
  return `${minX} ${minY} ${vw} ${vh}`
}

/** 哪些 key 是品牌（官方矢量，viewBox 用 estimateViewBox 现算） */
export const BRAND_ICON_KEYS = new Set(Object.keys(BRAND_PATHS))

/** 用户指定新增的那 6 个图标的 key */
export const PRESET_ICON_KEYS = new Set(Object.keys(PRESET_PATHS))

/**
 * 取某个图标的 path 列表。
 *
 * @param {string} key 图标 key
 * @returns {string[]} path 的 d 属性数组
 */
export function accountIconPaths(key) {
  if (BRAND_PATHS[key]) return [BRAND_PATHS[key]]
  const preset = PRESET_PATHS[key]
  if (preset) return preset.slice()
  return []
}

/**
 * 判断某个 key 是不是品牌图标（品牌是「一条 path + 根节点统一填充」）。
 *
 * ★ 语义保持原样：只认品牌表 ★
 *   新加的 6 个预设图标不是品牌，也不是原来的线性图标，
 *   所以这里对它们返回 false —— 调用方（AccountIcon.vue）拿它只做展示区分，
 *   真正决定怎么画的逻辑在 accountIconSvg 里。
 *
 * @param {string} key 图标 key
 * @returns {boolean}
 */
export function isBrandIcon(key) {
  return !!BRAND_PATHS[key]
}

/**
 * 判断某个 key 是不是用户指定新增的那 6 个图标。
 *
 * @param {string} key 图标 key
 * @returns {boolean}
 */
export function isPresetIcon(key) {
  return !!PRESET_PATHS[key]
}

/**
 * 生成图标 SVG。
 *
 * ★ 品牌和预设的画法其实完全一致 ★
 *   都是「根节点 fill=color + fill-rule=evenodd，子节点只有 d」：
 *     - 根节点给颜色 → 全图单色，跟着账户主题色/明暗模式走，风格统一
 *     - fill-rule=evenodd → 路径里的孔洞靠子路径挖出来
 *       （官方品牌路径依赖它，少了 Mastercard 两个圆会叠成实心块；
 *         预设里「圆形 + 内嵌镂空图案」那几个也一样靠它）
 *   区别只在 viewBox 来源：
 *     - 品牌路径坐标系各不相同（24x24 / 1024x1024 混着），
 *       必须按真实包围盒裁掉留白，小尺寸下才够大 → estimateViewBox
 *     - 用户给的 6 个是同一套 1024 画布画的成品，
 *       统一按包围盒取正方形视口 → PRESET_VIEW_BOXES
 *   未知 key 返回空串（调用方兜底显示账户名首字符）。
 *
 * @param {string} key 图标 key
 * @param {object} opts { size, color }
 * @returns {string} SVG 源码
 */
export function accountIconSvg(key, opts = {}) {
  const size = Number(opts.size) > 0 ? Number(opts.size) : 24
  const color = opts.color || 'currentColor'

  // ---- 品牌：一条官方 path，根节点统一填充 ----
  if (isBrandIcon(key)) {
    const viewBox = estimateViewBox(accountIconPaths(key))
    const body = `<path d="${BRAND_PATHS[key]}"/>`
    return (
      `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${viewBox}" ` +
      `width="${size}" height="${size}" fill="${color}" fill-rule="evenodd">` +
      body +
      `</svg>`
    )
  }

  // ---- 预设（用户指定 6 个）：正方形视口 + 根节点统一染色 ----
  const preset = PRESET_PATHS[key]
  if (preset) {
    const body = preset.map((d) => `<path d="${d}"/>`).join('')
    return (
      `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${PRESET_VIEW_BOXES[key]}" ` +
      `width="${size}" height="${size}" fill="${color}" fill-rule="evenodd">` +
      body +
      `</svg>`
    )
  }

  return ''
}

/**
 * 生成 data URI（给 <image> 的 src 用）。
 *
 * ★ 颜色必须是真实色值 ★
 *   data URI 是独立图片文档，CSS 变量（var(--app-x)）在里面不存在，
 *   fill/stroke 拿到无效值 -> 图标透明（这个坑踩过一次）。
 *   所以调用方（页面）传进来的必须是 hex，不能是 var(--app-text-2)。
 *
 * @param {string} key 图标 key
 * @param {object} opts { size, color }
 * @returns {string} data URI
 */
export function accountIconDataUri(key, opts = {}) {
  const svg = accountIconSvg(key, opts)
  if (!svg) return ''
  return 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg)
}
